.version 8.0
.target sm_89
.address_size 64

.visible .entry depthwise_conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 H_out,
    .param .u32 W_out
)
{
    .reg .b64 %rd<20>;
    .reg .b32 %r<40>;
    .reg .f32 %f<10>;
    .reg .pred %p<12>;

    ld.param.u64 %rd0, [input_ptr];
    ld.param.u64 %rd1, [weight_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [output_ptr];

    ld.param.u32 %r0, [N];
    ld.param.u32 %r1, [C];
    ld.param.u32 %r2, [H];
    ld.param.u32 %r3, [W];
    ld.param.u32 %r4, [K];
    ld.param.u32 %r5, [stride];
    ld.param.u32 %r6, [padding];
    ld.param.u32 %r7, [dilation];
    ld.param.u32 %r8, [H_out];
    ld.param.u32 %r9, [W_out];

    cvta.to.global.u64 %rd0, %rd0;
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r10, %tid.x;
    mov.u32 %r11, %ctaid.x;
    mov.u32 %r12, %ntid.x;
    mad.lo.u32 %r13, %r11, %r12, %r10;

    setp.ge.u32 %p0, %r13, %r9;
    @%p0 bra DONE;

    mov.u32 %r14, %ctaid.y;
    mov.u32 %r15, %ctaid.z;

    div.u32 %r16, %r15, %r1;
    rem.u32 %r17, %r15, %r1;

    mul.lo.u32 %r18, %r13, %r5;
    sub.s32 %r19, %r18, %r6;

    setp.lt.s32 %p1, %r19, 0;
    setp.ge.s32 %p2, %r19, %r3;
    or.pred %p3, %p1, %p2;

    mov.f32 %f0, 0f00000000;

    mov.u32 %r20, 0;

LOOP_START:
    setp.ge.u32 %p4, %r20, %r4;
    @%p4 bra LOOP_END;

    mul.lo.u32 %r21, %r14, %r5;
    mul.lo.u32 %r22, %r20, %r7;
    add.s32 %r23, %r21, %r22;
    sub.s32 %r24, %r23, %r6;

    setp.lt.s32 %p5, %r24, 0;
    setp.ge.s32 %p6, %r24, %r2;
    or.pred %p7, %p5, %p6;
    or.pred %p8, %p7, %p3;

    @%p8 bra SKIP;

    mad.lo.u32 %r25, %r16, %r1, %r17;
    mad.lo.u32 %r26, %r25, %r2, %r24;
    mad.lo.u32 %r27, %r26, %r3, %r19;

    mul.wide.s32 %rd4, %r27, 4;
    add.s64 %rd5, %rd0, %rd4;
    ld.global.f32 %f1, [%rd5];

    mad.lo.u32 %r28, %r17, %r4, %r20;
    mul.wide.s32 %rd6, %r28, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f2, [%rd7];

    fma.rn.f32 %f0, %f1, %f2, %f0;

SKIP:
    add.u32 %r20, %r20, 1;
    bra LOOP_START;

LOOP_END:
    mul.wide.s32 %rd10, %r17, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f3, [%rd11];
    add.f32 %f0, %f0, %f3;

    mad.lo.u32 %r29, %r16, %r1, %r17;
    mad.lo.u32 %r30, %r29, %r8, %r14;
    mad.lo.u32 %r31, %r30, %r9, %r13;

    mul.wide.s32 %rd8, %r31, 4;
    add.s64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f0;

DONE:
    ret;
