        module = _get_ptx_module()

        block_x = 256
        grid_x = (W_out + block_x - 1) // block_x
        grid = (grid_x, H_out, N * C)
        block = (block_x, 1, 1)

        module.launch(
            "depthwise_conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[
                x, weight, bias, output,
                i32(N), i32(C), i32(H), i32(W),
                i32(K), i32(stride), i32(padding), i32(dilation),
                i32(H_out), i32(W_out),
